// Input: array of LIMS result objects.
// Each item: { site_id, analyte, observed_on, log10_conc, n_samples }
// Output: one item per (analyte, date) pair, shaped as a ww_api RoundRequest.

const results = $input.all()[0].json;
const byKey = {};

for (const r of results) {
  const key = `${r.analyte}::${r.observed_on}`;
  if (!byKey[key]) {
    byKey[key] = {
      analyte: r.analyte,
      observed_on: r.observed_on,
      observations: [],
      source: 'lims',
      actor: 'n8n-lims-ingest'
    };
  }
  byKey[key].observations.push({
    site_id: r.site_id,
    log10_conc: r.log10_conc,
    n_samples: r.n_samples || 1
  });
}

return Object.values(byKey).map(round => ({ json: round }));

